/** Pure player-form and captaincy rules. */

const clampForm = (value) => Math.min(3, Math.max(-3, value));

function applyMatchForm({ club, goalsFor, goalsAgainst, scorerIds = [] }) {
  if (!club?.players?.length) throw new TypeError('Form updates require a club with players.');
  if (![goalsFor, goalsAgainst].every(Number.isFinite)) throw new TypeError('Form updates require a valid score.');
  const resultDelta = goalsFor > goalsAgainst ? 1 : goalsFor === goalsAgainst ? 0 : -1;
  const scorers = new Set(scorerIds.map(String));

  return {
    ...club,
    players: club.players.map((player) => {
      const current = player.form ?? 0;
      if (!player.starting) return { ...player, form: current === 0 ? 0 : current - Math.sign(current) };
      const scoringDelta = scorers.has(String(player.id)) ? 1 : 0;
      return { ...player, form: clampForm(current + resultDelta + scoringDelta) };
    })
  };
}

function chooseDefaultCaptain(club) {
  if (!club?.players?.length) return null;
  const ranked = [...club.players].sort((a, b) => (b.morale ?? 70) - (a.morale ?? 70)
    || (b.age ?? 18) - (a.age ?? 18)
    || (b.rating ?? 50) - (a.rating ?? 50)
    || String(a.name).localeCompare(String(b.name)));
  return ranked[0].id;
}

function captaincyBonus(club, activePlayers = club?.players?.filter((player) => player.starting) ?? []) {
  const captain = activePlayers.find((player) => String(player.id) === String(club?.captainId));
  return captain ? Math.max(0, ((captain.morale ?? 70) - 50) / 50) : 0;
}


/* src/domain/scouting.js */
/** Pure opponent scouting and squad-depth recommendations. */

const position = (player) => player.position ?? player.pos;
const average = (values) => values.length ? values.reduce((total, value) => total + value, 0) / values.length : 0;
const title = (value) => value.charAt(0).toUpperCase() + value.slice(1);

function scoutClub(club) {
  if (!club?.players?.length) throw new TypeError('Scouting requires a club with players.');
  const units = {
    defense: average(club.players.filter((player) => ['GK', 'DEF'].includes(position(player))).map((player) => player.rating ?? 50)),
    midfield: average(club.players.filter((player) => position(player) === 'MID').map((player) => player.rating ?? 50)),
    attack: average(club.players.filter((player) => position(player) === 'FWD').map((player) => player.rating ?? 50))
  };
  const strongestUnit = Object.entries(units).sort(([, left], [, right]) => right - left)[0][0];
  const likelyTactic = strongestUnit === 'attack' ? 'counter' : strongestUnit === 'midfield' ? 'control' : 'press';
  const recommendedTactic = { counter: 'control', control: 'press', press: 'counter' }[likelyTactic];
  const descriptions = {
    attack: 'Their forwards are the danger. Deny transition space and make them defend longer possessions.',
    midfield: 'Their midfield sets the rhythm. Pressure their buildup before they can control the match.',
    defense: 'Their back line is their platform. Draw them forward and attack the space they leave.'
  };

  return {
    strongestUnit,
    likelyTactic,
    recommendedTactic,
    summary: descriptions[strongestUnit],
    evidence: `${title(strongestUnit)} ${Math.round(units[strongestUnit])} · likely ${likelyTactic}`,
    units
  };
}

const readiness = (player) => (player.rating ?? 50) + (player.form ?? 0) * 1.5
  + ((player.fitness ?? 100) - 75) * 0.1 + ((player.morale ?? 70) - 70) * 0.04;

function recommendRotation(club) {
  if (!club?.players?.length) return null;
  const starters = club.players.filter((player) => player.starting);
  const bench = club.players.filter((player) => !player.starting);
  const candidates = [];

  for (const outgoing of starters) {
    for (const incoming of bench.filter((player) => position(player) === position(outgoing))) {
      const gain = readiness(incoming) - readiness(outgoing);
      if (gain >= 1) candidates.push({ outgoing, incoming, gain });
    }
  }

  const best = candidates.sort((left, right) => right.gain - left.gain)[0];
  if (!best) return null;
  const reason = (best.outgoing.fitness ?? 100) < 75
    ? `${best.outgoing.name} is carrying fatigue.`
    : `${best.incoming.name} has the stronger current readiness.`;
  return {
    outgoingId: best.outgoing.id,
    incomingId: best.incoming.id,
    outgoingName: best.outgoing.name,
    incomingName: best.incoming.name,
    position: position(best.outgoing),
    reason
  };
}


/* src/domain/objectives.js */
/** Pure season-objective and board-confidence rules. */

const clampConfidence = (value) => Math.min(95, Math.max(20, Math.round(value)));

function createSeasonObjective({ club, clubs, totalMatches }) {
  if (club?.id === undefined || club?.id === null || !Array.isArray(clubs) || !clubs.length || !Number.isInteger(totalMatches) || totalMatches < 1) {
    throw new TypeError('A season objective requires a club, league clubs, and match count.');
  }
  const reputationRank = [...clubs].sort((left, right) => (right.reputation ?? 60) - (left.reputation ?? 60)
    || String(left.name).localeCompare(String(right.name))).findIndex((entry) => String(entry.id) === String(club.id)) + 1;
  if (!reputationRank) throw new Error(`Club ${club.id} was not found in the league.`);

  const tier = reputationRank <= 2
    ? { targetPosition: 2, pointsPerMatch: 1.75, label: 'Challenge for the title' }
    : reputationRank <= Math.ceil(clubs.length * 0.625)
      ? { targetPosition: Math.ceil(clubs.length / 2), pointsPerMatch: 1.35, label: 'Finish in the top half' }
      : { targetPosition: Math.max(clubs.length - 2, 1), pointsPerMatch: 1, label: 'Build a competitive foundation' };

  return {
    ...tier,
    targetPoints: Math.round(totalMatches * tier.pointsPerMatch),
    totalMatches,
    reputationRank
  };
}

function evaluateBoardConfidence({ objective, position, points, matchesPlayed }) {
  if (!objective || !Number.isInteger(position) || position < 1 || !Number.isFinite(points) || !Number.isInteger(matchesPlayed) || matchesPlayed < 0) {
    throw new TypeError('Board confidence requires an objective and current season progress.');
  }
  const progress = Math.min(1, matchesPlayed / objective.totalMatches);
  const expectedPoints = objective.targetPoints * progress;
  const pointsDelta = points - expectedPoints;
  const positionDelta = (objective.targetPosition - position) * 5 * Math.min(1, matchesPlayed / 4);
  const value = clampConfidence(60 + pointsDelta * 2 + positionDelta);
  const status = value >= 78 ? 'Delighted' : value >= 58 ? 'Supportive' : value >= 40 ? 'Watchful' : 'Concerned';
  const met = matchesPlayed >= objective.totalMatches && position <= objective.targetPosition;

  return { value, status, expectedPoints: Math.round(expectedPoints), met };
}


/* src/domain/simulation.js */

/**
 * Deterministic, host-independent match rules.
 *
 * A resolver receives a locked league snapshot and returns a new result. It
 * does not read clocks, storage, browser state, or external services.
 */

const TACTIC_MODIFIERS = Object.freeze({
  balanced: 0,
  press: 0.8,
  counter: 0.35,
  control: 0.6
});

const TACTIC_MATCHUPS = Object.freeze({
  press: Object.freeze({ control: 0.7, counter: -0.7 }),
  control: Object.freeze({ counter: 0.7, press: -0.7 }),
  counter: Object.freeze({ press: 0.7, control: -0.7 }),
  balanced: Object.freeze({})
});

function tacticMatchup(tactic, opponentTactic) {
  return TACTIC_MATCHUPS[tactic]?.[opponentTactic] ?? 0;
}

function random(seed) {
  let value = (seed + 0x6d2b79f5) | 0;
  value = Math.imul(value ^ (value >>> 15), value | 1);
  value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
  return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
}

function poisson(lambda, seed) {
  const limit = Math.exp(-lambda);
  let product = 1;
  let goals = 0;
  let cursor = seed;
  do {
    goals += 1;
    cursor += 1;
    product *= random(cursor);
  } while (product > limit && goals < 8);
  return { goals: goals - 1, seed: cursor };
}

function createEvents(homeClub, awayClub, homeGoals, awayGoals, seed) {
  const events = [];
  const goals = [
    ...Array.from({ length: homeGoals }, (_, index) => ({ teamId: homeClub.id, teamName: homeClub.name, side: 'home', index })),
    ...Array.from({ length: awayGoals }, (_, index) => ({ teamId: awayClub.id, teamName: awayClub.name, side: 'away', index }))
  ];

  goals.forEach((goal, index) => {
    const minute = 5 + Math.floor(random(seed + 100 + index * 17) * 84);
    events.push({
      minute,
      type: 'goal',
      teamId: goal.teamId,
      side: goal.side,
      text: `${goal.teamName} find the breakthrough after a sharp attacking move.`
    });
  });

  events.sort((a, b) => a.minute - b.minute);
  if (!events.length) {
    events.push({
      minute: 45,
      type: 'match-note',
      teamId: null,
      side: null,
      text: 'A tense spell in midfield with neither side giving ground.'
    });
  }
  return events;
}

function validateLineup(club) {
  const starters = club.players.filter((player) => player.starting);
  const counts = starters.reduce((result, player) => {
    result[player.position] = (result[player.position] ?? 0) + 1;
    return result;
  }, {});

  return {
    valid: starters.length === 11 && (counts.GK ?? 0) === 1 && (counts.DEF ?? 0) >= 3 && (counts.MID ?? 0) >= 2 && (counts.FWD ?? 0) >= 1,
    starters,
    counts
  };
}

function teamStrength(club, tactic = 'balanced') {
  const lineup = validateLineup(club).starters;
  const active = lineup.length === 11 ? lineup : [...club.players].sort((a, b) => b.rating - a.rating).slice(0, 11);
  const average = active.reduce((total, player) => total + player.rating * (0.76 + player.fitness / 420), 0) / Math.max(active.length, 1);
  const averageMorale = active.reduce((total, player) => total + (player.morale ?? 70), 0) / Math.max(active.length, 1);
  const averageForm = active.reduce((total, player) => total + (player.form ?? 0), 0) / Math.max(active.length, 1);
  const moraleModifier = (averageMorale - 70) / 14;
  return average + moraleModifier + averageForm * 0.45 + captaincyBonus(club, active)
    + (club.preparationBonus ?? 0) + (TACTIC_MODIFIERS[tactic] ?? 0) + club.reputation * 0.04;
}

function resolveFixture({ fixture, homeClub, awayClub, homeTactic = 'balanced', awayTactic = 'balanced', seed = 1 }) {
  if (fixture.status === 'played') {
    throw new Error(`Fixture ${fixture.id} has already been resolved.`);
  }

  const homeStrength = teamStrength(homeClub, homeTactic) + tacticMatchup(homeTactic, awayTactic);
  const awayStrength = teamStrength(awayClub, awayTactic) + tacticMatchup(awayTactic, homeTactic);
  const difference = (homeStrength - awayStrength) / 12;
  const homeExpected = Math.max(0.25, 1.28 + difference);
  const awayExpected = Math.max(0.2, 1.02 - difference);
  const homeGoals = poisson(homeExpected, seed);
  const awayGoals = poisson(awayExpected, homeGoals.seed);
  const finalHomeGoals = Math.min(homeGoals.goals, 6);
  const finalAwayGoals = Math.min(awayGoals.goals, 6);

  return {
    fixtureId: fixture.id,
    resolverVersion: '0.1.0',
    seed,
    homeClubId: homeClub.id,
    awayClubId: awayClub.id,
    homeGoals: finalHomeGoals,
    awayGoals: finalAwayGoals,
    events: createEvents(homeClub, awayClub, finalHomeGoals, finalAwayGoals, seed),
    publishedAt: null
  };
}

function applyResult(club, goalsFor, goalsAgainst) {
  const result = goalsFor > goalsAgainst ? 'win' : goalsFor === goalsAgainst ? 'draw' : 'loss';
  const points = result === 'win' ? 3 : result === 'draw' ? 1 : 0;
  return {
    ...club,
    stats: {
      ...club.stats,
      played: club.stats.played + 1,
      wins: club.stats.wins + (result === 'win' ? 1 : 0),
      draws: club.stats.draws + (result === 'draw' ? 1 : 0),
      losses: club.stats.losses + (result === 'loss' ? 1 : 0),
      goalsFor: club.stats.goalsFor + goalsFor,
      goalsAgainst: club.stats.goalsAgainst + goalsAgainst,
      points: club.stats.points + points
    }
  };
}


/* src/domain/offseason.js */
/** Host-independent season review and player progression rules. */

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const appearances = (player) => player.appearances ?? player.apps ?? 0;
const goals = (player) => player.goals ?? 0;
const points = (club) => club.stats?.points ?? club.stats?.pts ?? 0;
const goalDifference = (club) => (club.stats?.goalsFor ?? club.stats?.gf ?? 0) - (club.stats?.goalsAgainst ?? club.stats?.ga ?? 0);

function stableRoll(seed, id) {
  let value = Number(seed) || 1;
  for (const character of String(id)) value = Math.imul(value ^ character.charCodeAt(0), 2654435761);
  value ^= value >>> 16;
  return (value >>> 0) / 4294967296;
}

function rankClubs(clubs) {
  return [...clubs].sort((a, b) => points(b) - points(a) || goalDifference(b) - goalDifference(a) || String(a.name).localeCompare(String(b.name)));
}

function playerSummary(player) {
  return {
    id: player.id,
    name: player.name,
    position: player.position ?? player.pos,
    age: player.age,
    appearances: appearances(player),
    goals: goals(player),
    rating: player.rating,
    ratingChange: player.rating - (player.seasonStartRating ?? player.rating)
  };
}

function createSeasonReview({ season, clubs, userClubId }) {
  if (!Number.isInteger(season) || season < 1 || !Array.isArray(clubs) || !clubs.length) {
    throw new TypeError('A season review requires a season number and clubs.');
  }
  const standings = rankClubs(clubs);
  const userClub = clubs.find((club) => String(club.id) === String(userClubId));
  if (!userClub) throw new Error(`User club ${userClubId} was not found.`);
  const allPlayers = clubs.flatMap((club) => club.players.map((player) => ({ ...playerSummary(player), clubId: club.id, clubName: club.name })));
  const scorerOrder = (a, b) => b.goals - a.goals || b.appearances - a.appearances || b.rating - a.rating || a.name.localeCompare(b.name);
  const squad = userClub.players.map(playerSummary).sort(scorerOrder);
  const champion = standings[0];
  const topScorer = [...allPlayers].sort(scorerOrder)[0];
  return {
    season,
    champion: { clubId: champion.id, clubName: champion.name, points: points(champion) },
    userClub: { clubId: userClub.id, clubName: userClub.name, position: standings.indexOf(userClub) + 1, points: points(userClub) },
    topScorer,
    clubPlayerOfSeason: squad[0],
    squad
  };
}

function playerProgression(player, seed) {
  const age = player.age ?? 18;
  const rating = player.rating ?? 50;
  const potential = Math.max(rating, player.potential ?? rating);
  const played = appearances(player);
  const roll = stableRoll(seed, player.id);
  let delta = 0;

  if (age <= 23 && played >= 5 && rating < potential) delta = 1 + (roll > 0.72 ? 1 : 0);
  else if (age <= 29 && played >= 10 && rating < potential && roll > 0.55) delta = 1;
  else if (age >= 35) delta = -2;
  else if (age >= 32 && (played < 10 || roll > 0.35)) delta = -1;
  else if (age >= 30 && played < 5 && roll > 0.5) delta = -1;

  const nextRating = clamp(rating + delta, 40, potential);
  return {
    ...player,
    age: age + 1,
    rating: nextRating,
    fitness: Math.max(92, player.fitness ?? 92),
    morale: clamp((player.morale ?? 70) + 5, 40, 85),
    form: 0,
    appearances: 0,
    apps: 0,
    goals: 0,
    seasonStartRating: nextRating
  };
}

function advanceOffseason({ clubs, seed = 1 }) {
  if (!Array.isArray(clubs) || !clubs.length) throw new TypeError('Offseason progression requires clubs.');
  const changes = [];
  const nextClubs = clubs.map((club, clubIndex) => ({
    ...club,
    players: club.players.map((player, playerIndex) => {
      const progressed = playerProgression(player, seed + clubIndex * 101 + playerIndex * 17);
      const delta = progressed.rating - player.rating;
      if (delta) changes.push({ clubId: club.id, playerId: player.id, playerName: player.name, delta, previousRating: player.rating, rating: progressed.rating });
      return progressed;
    }),
    stats: { played: 0, wins: 0, draws: 0, losses: 0, goalsFor: 0, goalsAgainst: 0, points: 0 }
  }));
  return { clubs: nextClubs, changes, seed: (Number(seed) + 1) >>> 0 };
}


/* src/domain/training.js */
/** Pure weekly preparation and morale rules. */

const TRAINING_FOCUSES = Object.freeze({
  recovery: Object.freeze({ fitness: 8, morale: 1, preparationBonus: 0 }),
  balanced: Object.freeze({ fitness: 3, morale: 2, preparationBonus: 0.3 }),
  intensity: Object.freeze({ fitness: -3, morale: 0, preparationBonus: 0.9 })
});

const clampTrainingValue = (value, min, max) => Math.min(max, Math.max(min, value));

function applyTrainingPlan({ club, focus = 'balanced' }) {
  if (!club?.players?.length) throw new TypeError('Training requires a club with players.');
  const plan = TRAINING_FOCUSES[focus];
  if (!plan) throw new Error(`Unknown training focus: ${focus}`);

  return {
    ...club,
    preparationFocus: focus,
    preparationBonus: plan.preparationBonus,
    players: club.players.map((player) => ({
      ...player,
      fitness: clampTrainingValue((player.fitness ?? 100) + plan.fitness, 50, 100),
      morale: clampTrainingValue((player.morale ?? 70) + plan.morale, 35, 90)
    }))
  };
}

function applyMatchMorale({ club, goalsFor, goalsAgainst }) {
  if (!club?.players?.length) throw new TypeError('Morale updates require a club with players.');
  if (![goalsFor, goalsAgainst].every(Number.isFinite)) throw new TypeError('Morale updates require a valid score.');
  const resultDelta = goalsFor > goalsAgainst ? 3 : goalsFor === goalsAgainst ? 1 : -2;

  return {
    ...club,
    preparationBonus: 0,
    players: club.players.map((player) => ({
      ...player,
      morale: clampTrainingValue((player.morale ?? 70) + resultDelta + (player.starting ? 0 : -1), 35, 90)
    }))
  };
}

function recommendTrainingFocus(club) {
  if (!club?.players?.length) return 'balanced';
  const averageFitness = club.players.reduce((total, player) => total + (player.fitness ?? 100), 0) / club.players.length;
  return averageFitness < 76 ? 'recovery' : 'balanced';
}


